python -c "
import xml.etree.ElementTree as ET
import glob, os

for xml_file in sorted(glob.glob('data/nasa_raw/*.xml')):
    filename = os.path.basename(xml_file)
    print('='*70)
    print(filename)
    tree = ET.parse(xml_file)
    root = tree.getroot()

    # Collect all tags containing 'solar', 'sun', 'incidence', 'phase', 'emission'
    solar_info = {}
    for elem in root.iter():
        tag = elem.tag.split('}')[-1]
        text = (elem.text or '').strip()
        if any(k in tag.lower() for k in ['solar', 'sun', 'incidence', 'phase', 'emission']):
            if text:
                solar_info[tag] = text

    for k, v in solar_info.items():
        print(f'  {k}: {v}')
"

